package com.commercecore.order;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.UUID;@RestController@RequestMapping("/api/v1/staff/orders")@SecurityRequirement(name="bearerAuth")public class StaffOrderController{private final OrderService orders;private final PaidCancellationService paid;public StaffOrderController(OrderService o,PaidCancellationService p){orders=o;paid=p;}@GetMapping OrderDtos.PageResponse<OrderDtos.OrderResponse>list(@RequestParam(required=false)String orderNumber,@RequestParam(required=false)OrderStatus status,@RequestParam(required=false)UUID customerId,@RequestParam(required=false)String customerEmail,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant createdFrom,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant createdTo,@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(100)int size){return orders.staffOrders(orderNumber,status,customerId,customerEmail,createdFrom,createdTo,page,size);}@GetMapping("/{id}")OrderDtos.OrderResponse get(@PathVariable UUID id){return orders.staffOrder(id);}@PostMapping("/{id}/cancel")OrderDtos.OrderResponse cancel(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return orders.cancelStaff(actor(jwt),id);}@PostMapping("/{id}/cancel-paid")OrderDtos.OrderResponse cancelPaid(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return paid.cancel(actor(jwt),id);}@PostMapping("/{id}/processing")OrderDtos.OrderResponse processing(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return orders.processing(actor(jwt),id);}@PostMapping("/{id}/shipment")OrderDtos.OrderResponse shipment(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id,@Valid@RequestBody OrderDtos.ShipmentRequest request){return orders.createShipment(actor(jwt),id,request);}@PostMapping("/{id}/tracking-events")OrderDtos.OrderResponse track(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id,@Valid@RequestBody OrderDtos.TrackingEventRequest request){return orders.addTracking(actor(jwt),id,request);}@PostMapping("/{id}/ship")OrderDtos.OrderResponse ship(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return orders.ship(actor(jwt),id);}@PostMapping("/{id}/deliver")OrderDtos.OrderResponse deliver(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return orders.deliver(actor(jwt),id);}private static UUID actor(Jwt jwt){return UUID.fromString(jwt.getSubject());}}
